SELECT

FROM ai_data_audit_field
WHERE tenant_id = #{tenantId}
  AND event_id = #{eventId}

    AND (
        field_code = #{query.fieldCode}
        OR column_name = #{query.fieldCode}
        OR LOWER(REPLACE(field_code, '_', '')) = LOWER(REPLACE(#{query.fieldCode}, '_', ''))
        OR LOWER(REPLACE(IFNULL(column_name, ''), '_', '')) = LOWER(REPLACE(#{query.fieldCode}, '_', ''))
    )


    AND relation_key = #{query.relationKey}


    AND target_record_id = #{query.targetRecordId}


ORDER BY relation_key ASC, target_record_id ASC, field_code ASC, id ASC

SELECT

FROM ai_data_audit_field
WHERE tenant_id = #{tenantId}
  AND event_id = #{eventId}
  AND id = #{id}
LIMIT 1

SELECT COUNT(1)
FROM ai_data_audit_field
WHERE tenant_id = #{tenantId}
  AND event_id = #{eventId}
